def m(s):
    match s:
        case 0 | 1 as small:
            return ('small', small)
        case True:
            return 'true'
        case int(n) if n > 2:
            return ('big int', n)
        case str() as t:
            return ('str', t.upper())
        case [x, y]:
            return ('pair', x, y)
        case [1, *rest]:
            return ('starts1', rest)
        case [a, [b, c]]:
            return ('nested', a, b, c)
        case {'x': x, **others}:
            return ('map', x, others)
        case {'kind': 'a', 'v': [v]}:
            return ('kind', v)
        case P(0, y=yy):
            return ('P0', yy)
        case P(x, y):
            return ('P', x, y)
        case None:
            return 'none'
        case float():
            return 'float'
        case _:
            return 'other'
print(m(0))

