class Base:
    kind = 'base'
    def __init__(self, v):
        self.v = v
    def __repr__(self):
        return f'{type(self).__name__}({self.v!r})'
    def __eq__(self, other):
        return isinstance(other, Base) and self.v == other.v
    def __lt__(self, other):
        return self.v < other.v
    def __hash__(self):
        return hash(self.v)
    @property
    def double(self):
        return self.v * 2
    @classmethod
    def make(cls, v):
        return cls(v)
    @staticmethod
    def helper(x):
        return x + 1
class Child(Base):
    kind = 'child'
    def __init__(self, v, w=1):
        super().__init__(v)
        self.w = w
    def __str__(self):
        return 'Child<' + str(self.v) + ',' + str(self.w) + '>'
    def __bool__(self):
        return bool(self.w)
    def __len__(self):
        return self.w
items = [Child(6), Base(5), Child.make(2)]
print(items, sorted(items), [str(i) for i in items], [bool(i) for i in items])
print(Child(1) == Base(1), Child.kind, Base.helper(1), items[0].double, Child.__mro__, Child.__name__, Child.__qualname__)
print(isinstance(items[0], Base), issubclass(Child, Base), type(items[0]).__name__, len(items[0]))
try:
    items[1].missing
except AttributeError as e:
    print(e)
try:
    Base.double.fset(items[0], 3)
except Exception as e:
    print(type(e).__name__, e)
try:
    items[0].double = 5
except AttributeError as e:
    print(e)
print(sorted({Base(2), Base(2), Child(2)}, key=lambda b: (type(b).__name__, b.v)))

