class Base:
    kind = 'base'
    def __init__(self, v):
        self.v = v
    def __repr__(self):
        return f'{type(self).__name__}({self.v!r})'
    def __eq__(self, other):
        return isinstance(other, Base) and self.v == other.v
    def __lt__(self, other):
        return self.v < other.v
    def __hash__(self):
        return hash(self.v)
    @property
    def double(self):
        return self.v * 2
    @classmethod
    def make(cls, v):
        return cls(v)
    @staticmethod
    def helper(x):
        return x + 1
class Child(Base):
    kind = 'child'
    def __init__(self, v, w=2):
        super().__init__(v)
        self.w = w
    def __str__(self):
        return 'Child<' + str(self.v) + ',' + str(self.w) + '>'
    def __bool__(self):
        return bool(self.w)
    def __len__(self):
        return self.w
