class Strict(string.Formatter):
    def check_unused_args(self, used, args, kwargs):
        extra = set(kwargs) - used
        if extra: raise ValueError('unused %s' % sorted(extra))
    def get_value(self, key, args, kwargs):
        if isinstance(key, str) and key not in kwargs: return '<%s>' % key
        return super().get_value(key, args, kwargs)
    def format_field(self, value, spec):
        return '[' + super().format_field(value, spec) + ']'
    def convert_field(self, value, conv):
        if conv == 'u': return str(value).upper()
        return super().convert_field(value, conv)
